-- case 1: [A01] rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItemID ascending; reorder and target levels differ on every row
CREATE PROCEDURE [AgreedTests].[test 01 [A01 rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItem…]
AS
BEGIN
  EXEC tSQLt.FakeTable @TableName = N'[Warehouse].[StockItemHoldings]';
  INSERT INTO [Warehouse].[StockItemHoldings] ([StockItemID], [QuantityOnHand], [BinLocation], [LastStocktakeQuantity], [LastCostPrice], [ReorderLevel], [TargetStockLevel]) VALUES
    (2147483647, 10, N'A-1', 10, 1.00, 1, 2),
    (1000, 10, N'A-1', 10, 1.00, 3, 4),
    (0, 10, N'A-1', 10, 1.00, 0, -1),
    (-1, 10, N'A-1', 10, 1.00, 7, 70),
    (-2147483648, 10, N'A-1', 10, 1.00, 2147483647, -2147483648);
  CREATE TABLE #Expected (
    [Quantity On Hand] int NULL,
    [Bin Location] nvarchar(20) NULL,
    [Last Stocktake Quantity] int NULL,
    [Last Cost Price] decimal(18,2) NULL,
    [Reorder Level] int NULL,
    [Target Stock Level] int NULL,
    [WWI Stock Item ID] int NULL
  );
  CREATE TABLE #Actual (
    [Quantity On Hand] int NULL,
    [Bin Location] nvarchar(20) NULL,
    [Last Stocktake Quantity] int NULL,
    [Last Cost Price] decimal(18,2) NULL,
    [Reorder Level] int NULL,
    [Target Stock Level] int NULL,
    [WWI Stock Item ID] int NULL
  );
  INSERT INTO #Expected ([Quantity On Hand], [Bin Location], [Last Stocktake Quantity], [Last Cost Price], [Reorder Level], [Target Stock Level], [WWI Stock Item ID]) VALUES
    (10, N'A-1', 10, 1, 2147483647, -2147483648, -2147483648),
    (10, N'A-1', 10, 1, 7, 70, -1),
    (10, N'A-1', 10, 1, 0, -1, 0),
    (10, N'A-1', 10, 1, 3, 4, 1000),
    (10, N'A-1', 10, 1, 1, 2, 2147483647);
  INSERT INTO #Actual
  EXEC Integration.GetStockHoldingUpdates;
  EXEC tSQLt.AssertEqualsTable @Expected = N'#Expected', @Actual = N'#Actual';
END;
GO
